export const MASTER_KECAMATAN_INDONESIA: KecamatanItem[] = RAW_DATA.map(([kode, kecamatan, kota, provinsi, kodepos]) => ({
  kode,
  kecamatan,
  kota,
  provinsi,
  kodepos,
}));

// Quick Search across all kecamatan, kota, kodepos
export function searchKecamatan(query: string, limit = 50): KecamatanItem[] {
  if (!query || !query.trim()) return MASTER_KECAMATAN_INDONESIA.slice(0, limit);
  const q = query.trim().toLowerCase();
  const results: KecamatanItem[] = [];
  
  for (const item of MASTER_KECAMATAN_INDONESIA) {
    if (
      item.kecamatan.toLowerCase().includes(q) ||
      item.kota.toLowerCase().includes(q) ||
      item.kodepos.includes(q) ||
      item.provinsi.toLowerCase().includes(q)
    ) {
      results.push(item);
      if (results.length >= limit) break;
    }
  }
  return results;
}

// Hierarchical helpers (Provinsi -> Kota -> Kecamatan)
export function getAllProvinces(): string[] {
  const set = new Set<string>();
  for (const item of MASTER_KECAMATAN_INDONESIA) {
    if (item.provinsi) set.add(item.provinsi);
  }
  return Array.from(set).sort();
}

export function getCitiesByProvince(provinceName: string): string[] {
  if (!provinceName) return [];
  const set = new Set<string>();
  for (const item of MASTER_KECAMATAN_INDONESIA) {
    if (item.provinsi.toLowerCase() === provinceName.toLowerCase() && item.kota) {
      set.add(item.kota);
    }
  }
  return Array.from(set).sort();
}

export function getDistrictsByCity(cityName: string): KecamatanItem[] {
  if (!cityName) return [];
  const results: KecamatanItem[] = [];
  for (const item of MASTER_KECAMATAN_INDONESIA) {
    if (item.kota.toLowerCase() === cityName.toLowerCase()) {
      results.push(item);
    }
  }
  return results.sort((a, b) => a.kecamatan.localeCompare(b.kecamatan));
}
